for k,v in repl.items():body=body.replace('@@'+k+'@@',v)
assert '@@' not in body
body+=bibliography(6,'Deep Energy-Based Models и Normalizing Flows. Density estimation, sampling, invertibility и ограничения представления распределений')+registry(out,reg)
